import{z as n,x as d,o as e,c as B,q as t,j as l,D as E,d as s,s as i,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"SSRF","description":"","frontmatter":{"title":"SSRF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssrf.md","filePath":"cs/ssrf.md","lastUpdated":1791063341000}'),p={name:"cs/ssrf.md"};function S(D,a,c,C,h,m){const A=d("Mermaid");return e(),B("div",null,[a[2]||(a[2]=t('<h1 id="ssrf" tabindex="-1">SSRF <a class="header-anchor" href="#ssrf" aria-label="Permalink to &quot;SSRF&quot;">​</a></h1><div class="epigraph"><p>服务器若把用户供给的 URL 拿去自己请求，就把防火墙后面的身份借给了输入。防御是允许名单、禁内网与重定向，而不是事后看返回体像不像 HTML。</p><footer>—— 据 OWASP SSRF；CWE-918；对照[注入](/cs/injection-boundary)</footer></div><p>上一课<a href="/cs/clickjacking">点击劫持</a>借用户手指。缺口是<strong>借服务器的网络位置</strong>。云元数据、内网管理口是典型受害者。不给打内网的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Webhook、预览、换图：应用去抓 URL。若跟重定向、改写 IP、DNS 再绑定，允许名单会被绕——只陈述要钉死解析与禁止私网段。缺口是出站策略。</p><p><span class="marginnote">SSRF 的直觉类比：让公司保安替一个陌生访客去送信。保安有进机房的门禁卡（服务器的内网身份），而信的内容和地址是外人写的——门禁再严，执行者被骗了就等于没设防。所以防线必须在「接单」这一步：只送白名单地址的信，而不是事后检查信封好看不好看。</span></p><h3 id="元数据服务" tabindex="-1">元数据服务 <a class="header-anchor" href="#元数据服务" aria-label="Permalink to &quot;元数据服务&quot;">​</a></h3><p>云实例角色凭证常在链路本地。SSRF 的危害是身份，不只是读 HTML。</p><p><span class="marginnote">为什么重要：云元数据服务（如 169.254.169.254）会直接返回该实例的临时访问凭证。一次看似「只是读了个内部页面」的 SSRF，实际效果可能是攻击者拿走整台实例的云角色——能读对象存储、能调管理 API。危害评估时按「身份泄露」算，不按「信息泄露」算。</span></p><p><span class="marginnote">CWE-918。课程禁止 SSRF 打靶教程。防御：允许名单主机、禁重定向、隔离出站。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照浏览器 CORS：那是读别人；SSRF 是服务器当客户端。下一课反序列化：输入变成对象图与代码路径。</p>',13)),(e(),l(o,null,{default:E(()=>[i(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20URL%5B%22%E7%94%A8%E6%88%B7%20URL%22%5D%20--%3E%20APP%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%E8%AF%B7%E6%B1%82%22%5D%0A%20%20APP%20--%3E%20INET%5B%22%E5%86%85%E7%BD%91%E6%88%96%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20APP%20--%3E%20ALLOW%5B%22%E5%85%81%E8%AE%B8%E5%90%8D%E5%8D%95%E4%B8%8E%E6%97%A0%E9%87%8D%E5%AE%9A%E5%90%91%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[s("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"最小特权：应用默认不应能碰元数据与管理网。网络分段后课会再收。反序列化下一课是进程内的输入变对象。",-1)),(e(),l(o,null,{default:E(()=>[i(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20INPUT%5B%22%E7%94%A8%E6%88%B7%E6%8F%90%E4%BA%A4%20URL%22%5D%20--%3E%20RESOLVE%5B%22%E7%AC%AC%E4%B8%80%E6%AD%A5%EF%BC%9A%E8%A7%A3%E6%9E%90%E5%9F%9F%E5%90%8D%E5%BE%97%20IP%22%5D%0A%20%20RESOLVE%20--%3E%20CHECK%5B%22%E6%A0%A1%E9%AA%8C%E8%AF%A5%20IP%20%E6%98%AF%E5%90%A6%E7%A7%81%E7%BD%91%E6%AE%B5%22%5D%0A%20%20CHECK%20--%3E%20PASS%5B%22%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%EF%BC%8C%E6%94%BE%E8%A1%8C%E8%AF%B7%E6%B1%82%22%5D%0A%20%20PASS%20--%3E%20FETCH%5B%22%E7%AC%AC%E4%BA%8C%E6%AD%A5%EF%BC%9A%E7%9C%9F%E6%AD%A3%E5%8F%91%E8%B5%B7%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20FETCH%20--%3E%20REBIND%5B%22%E5%9F%9F%E5%90%8D%E7%AC%AC%E4%BA%8C%E6%AC%A1%E8%A7%A3%E6%9E%90%E5%B7%B2%E6%8D%A2%E6%88%90%E5%86%85%E7%BD%91%20IP%22%5D%0A%20%20REBIND%20--%3E%20REACH%5B%22%E8%AF%B7%E6%B1%82%E7%9B%B4%E8%BE%BE%E5%86%85%E7%BD%91%E6%88%96%E5%85%83%E6%95%B0%E6%8D%AE%E6%9C%8D%E5%8A%A1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">DNS 再绑定就是上图的两步坑：校验用第一次解析的结果，请求时域名又解析了一次，两次答案可以不一样——「域名没变，门牌换了」。防御不是把校验写得更聪明，而是消除两步：钉死一次性解析（校验用的 IP 就是连接用的 IP），或出站走代理、由代理统一执行私网段拦截。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写元数据利用步骤。反序列化下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>点击借用户；SSRF 借服务器出站。</li><li>允许名单、禁私网、慎重定向。</li><li>危害常是云身份，不只是页面。</li><li>下一课反序列化。</li><li>出处：CWE-918；OWASP SSRF。</li></ul>',5))])}const f=n(p,[["render",S]]);export{P as __pageData,f as default};
